	__models__GongNoteShape__00000000_.Name = `01. Airport Message & Temporality-Note01AirportMessage`
	__models__GongNoteShape__00000000_.Identifier = `ref_models.Note01AirportMessage`
	__models__GongNoteShape__00000000_.Body = `01. Airport Message & Temporality Story

An [models.AIXMBasicMessage] exchanges aerodrome and heliport infrastructure via [models.BasicMessageMemberAIXMPropertyType].
Each feature ([models.AirportHeliportType], [models.RunwayType]) follows the AIXM Temporality Model: its state over time is carried
by [models.AirportHeliportTimeSliceType] and [models.RunwayTimeSliceType] slices bounded by ValidTime ([models.TimePrimitivePropertyType]).
`
	__models__GongNoteShape__00000000_.BodyHTML = `<p>01. Airport Message &amp; Temporality Story
<p>An <a href="/models#AIXMBasicMessage">models.AIXMBasicMessage</a> exchanges aerodrome and heliport infrastructure via <a href="/models#BasicMessageMemberAIXMPropertyType">models.BasicMessageMemberAIXMPropertyType</a>.
Each feature (<a href="/models#AirportHeliportType">models.AirportHeliportType</a>, <a href="/models#RunwayType">models.RunwayType</a>) follows the AIXM Temporality Model: its state over time is carried
by <a href="/models#AirportHeliportTimeSliceType">models.AirportHeliportTimeSliceType</a> and <a href="/models#RunwayTimeSliceType">models.RunwayTimeSliceType</a> slices bounded by ValidTime (<a href="/models#TimePrimitivePropertyType">models.TimePrimitivePropertyType</a>).
`
	__models__GongNoteShape__00000000_.X = 40.000000
	__models__GongNoteShape__00000000_.Y = 20.000000
	__models__GongNoteShape__00000000_.Width = 640.000000
	__models__GongNoteShape__00000000_.Height = 142.000000
	__models__GongNoteShape__00000000_.IsHidden = false
	__models__GongNoteShape__00000000_.Matched = false
	__models__GongNoteShape__00000000_.IsExpanded = false
	__models__GongNoteShape__00000001_.Name = `02. AirportHeliport, Availability, Usage & City-Note02AirportOverview`
	__models__GongNoteShape__00000001_.Identifier = `ref_models.Note02AirportOverview`
	__models__GongNoteShape__00000001_.Body = `02. AirportHeliport, Availability, Usage & City Story

[models.AirportHeliportTimeSliceType] holds core aerodrome identification (ICAO indicator, IATA code, ARP, elevation) and [models.CityType] served.
Operational hours use [models.AirportHeliportAvailabilityType], traffic permissions use [models.AirportHeliportUsageType], and operator authority uses [models.AirportHeliportResponsibilityOrganisationType].
`
	__models__GongNoteShape__00000001_.BodyHTML = `<p>02. AirportHeliport, Availability, Usage &amp; City Story
<p><a href="/models#AirportHeliportTimeSliceType">models.AirportHeliportTimeSliceType</a> holds core aerodrome identification (ICAO indicator, IATA code, ARP, elevation) and <a href="/models#CityType">models.CityType</a> served.
Operational hours use <a href="/models#AirportHeliportAvailabilityType">models.AirportHeliportAvailabilityType</a>, traffic permissions use <a href="/models#AirportHeliportUsageType">models.AirportHeliportUsageType</a>, and operator authority uses <a href="/models#AirportHeliportResponsibilityOrganisationType">models.AirportHeliportResponsibilityOrganisationType</a>.
`
