	__models__GongNoteShape__00000002_.Identifier = `ref_models.Note03HotSpotWorkArea`
	__models__GongNoteShape__00000002_.Body = `03. HotSpot, AltimeterSource, NonMovement & WorkArea Story

Aerodrome safety and construction features include [models.AirportHotSpotTimeSliceType] (collision risk locations), [models.AltimeterSourceTimeSliceType]
([models.AltimeterSourceStatusType]), [models.WorkAreaTimeSliceType] ([models.WorkareaActivityType]), and [models.SurveyControlPointTimeSliceType].
`
	__models__GongNoteShape__00000002_.BodyHTML = `<p>03. HotSpot, AltimeterSource, NonMovement &amp; WorkArea Story
<p>Aerodrome safety and construction features include <a href="/models#AirportHotSpotTimeSliceType">models.AirportHotSpotTimeSliceType</a> (collision risk locations), <a href="/models#AltimeterSourceTimeSliceType">models.AltimeterSourceTimeSliceType</a>
(<a href="/models#AltimeterSourceStatusType">models.AltimeterSourceStatusType</a>), <a href="/models#WorkAreaTimeSliceType">models.WorkAreaTimeSliceType</a> (<a href="/models#WorkareaActivityType">models.WorkareaActivityType</a>), and <a href="/models#SurveyControlPointTimeSliceType">models.SurveyControlPointTimeSliceType</a>.
`
