	__models__GongNoteShape__00000003_.Identifier = `ref_models.Note04Apron`
	__models__GongNoteShape__00000003_.Body = `04. Apron & ApronElement Story

[models.ApronTimeSliceType] and polygonal [models.ApronElementTimeSliceType] patches model aircraft parking and ramp areas,
with bearing strength in [models.SurfaceCharacteristicsType], operational status in [models.ApronAreaAvailabilityType], and rules in [models.ApronAreaUsageType].
`
	__models__GongNoteShape__00000003_.BodyHTML = `<p>04. Apron &amp; ApronElement Story
<p><a href="/models#ApronTimeSliceType">models.ApronTimeSliceType</a> and polygonal <a href="/models#ApronElementTimeSliceType">models.ApronElementTimeSliceType</a> patches model aircraft parking and ramp areas,
with bearing strength in <a href="/models#SurfaceCharacteristicsType">models.SurfaceCharacteristicsType</a>, operational status in <a href="/models#ApronAreaAvailabilityType">models.ApronAreaAvailabilityType</a>, and rules in <a href="/models#ApronAreaUsageType">models.ApronAreaUsageType</a>.
`
