	__models__GongNoteShape__00000004_.Identifier = `ref_models.Note05AircraftStand`
	__models__GongNoteShape__00000004_.Body = `05. AircraftStand, LoadingBridge, DeicingArea & Road Story

Ramp facilities include [models.AircraftStandTimeSliceType] (gate/stand coordinates and visual docking), [models.PassengerLoadingBridgeTimeSliceType],
[models.DeicingAreaTimeSliceType] pads, and airside [models.RoadTimeSliceType] segments, sharing [models.SurfaceCharacteristicsType] and [models.ApronAreaAvailabilityType].
`
	__models__GongNoteShape__00000004_.BodyHTML = `<p>05. AircraftStand, LoadingBridge, DeicingArea &amp; Road Story
<p>Ramp facilities include <a href="/models#AircraftStandTimeSliceType">models.AircraftStandTimeSliceType</a> (gate/stand coordinates and visual docking), <a href="/models#PassengerLoadingBridgeTimeSliceType">models.PassengerLoadingBridgeTimeSliceType</a>,
<a href="/models#DeicingAreaTimeSliceType">models.DeicingAreaTimeSliceType</a> pads, and airside <a href="/models#RoadTimeSliceType">models.RoadTimeSliceType</a> segments, sharing <a href="/models#SurfaceCharacteristicsType">models.SurfaceCharacteristicsType</a> and <a href="/models#ApronAreaAvailabilityType">models.ApronAreaAvailabilityType</a>.
`
	__models__GongNoteShape__00000004_.X = 40.000000
