	__models__GongNoteShape__00000005_.Name = `06. TouchDownLiftOff (TLOF) & SafeArea-Note06TLOF`
	__models__GongNoteShape__00000005_.Identifier = `ref_models.Note06TLOF`
	__models__GongNoteShape__00000005_.Body = `06. TouchDownLiftOff (TLOF) & SafeArea Story

Heliport landing pads are modeled by [models.TouchDownLiftOffTimeSliceType] (TLOF) and surrounding [models.TouchDownLiftOffSafeAreaTimeSliceType],
with load-bearing properties in [models.SurfaceCharacteristicsType], status in [models.ManoeuvringAreaAvailabilityType], and restrictions in [models.ManoeuvringAreaUsageType].
`
	__models__GongNoteShape__00000005_.BodyHTML = `<p>06. TouchDownLiftOff (TLOF) &amp; SafeArea Story
<p>Heliport landing pads are modeled by <a href="/models#TouchDownLiftOffTimeSliceType">models.TouchDownLiftOffTimeSliceType</a> (TLOF) and surrounding <a href="/models#TouchDownLiftOffSafeAreaTimeSliceType">models.TouchDownLiftOffSafeAreaTimeSliceType</a>,
with load-bearing properties in <a href="/models#SurfaceCharacteristicsType">models.SurfaceCharacteristicsType</a>, status in <a href="/models#ManoeuvringAreaAvailabilityType">models.ManoeuvringAreaAvailabilityType</a>, and restrictions in <a href="/models#ManoeuvringAreaUsageType">models.ManoeuvringAreaUsageType</a>.
`
