	__models__GongNoteShape__00000006_.Identifier = `ref_models.Note07Runway`
	__models__GongNoteShape__00000006_.Body = `07. Runway, RunwayElement & Surface Story

A [models.RunwayTimeSliceType] represents a physical landing strip (or FATO) composed of one or more [models.RunwayElementTimeSliceType] pavement sections,
characterized by PCN/pavement type ([models.SurfaceCharacteristicsType]), [models.ManoeuvringAreaAvailabilityType], and [models.ManoeuvringAreaUsageType].
`
	__models__GongNoteShape__00000006_.BodyHTML = `<p>07. Runway, RunwayElement &amp; Surface Story
<p>A <a href="/models#RunwayTimeSliceType">models.RunwayTimeSliceType</a> represents a physical landing strip (or FATO) composed of one or more <a href="/models#RunwayElementTimeSliceType">models.RunwayElementTimeSliceType</a> pavement sections,
characterized by PCN/pavement type (<a href="/models#SurfaceCharacteristicsType">models.SurfaceCharacteristicsType</a>), <a href="/models#ManoeuvringAreaAvailabilityType">models.ManoeuvringAreaAvailabilityType</a>, and <a href="/models#ManoeuvringAreaUsageType">models.ManoeuvringAreaUsageType</a>.
`
