	__models__GongNoteShape__00000014_.Body = `15. Stand, Apron, Deicing, TLOF Marking & Contamination Story

Ramp markings ([models.StandMarkingTimeSliceType], [models.ApronMarkingTimeSliceType], [models.DeicingAreaMarkingTimeSliceType]) use [models.MarkingElementType],
while SNOWTAM winter surface conditions are modeled by [models.AirportHeliportContaminationType], [models.RunwayContaminationType], and [models.SurfaceContaminationLayerType].
`
	__models__GongNoteShape__00000014_.BodyHTML = `<p>15. Stand, Apron, Deicing, TLOF Marking &amp; Contamination Story
<p>Ramp markings (<a href="/models#StandMarkingTimeSliceType">models.StandMarkingTimeSliceType</a>, <a href="/models#ApronMarkingTimeSliceType">models.ApronMarkingTimeSliceType</a>, <a href="/models#DeicingAreaMarkingTimeSliceType">models.DeicingAreaMarkingTimeSliceType</a>) use <a href="/models#MarkingElementType">models.MarkingElementType</a>,
while SNOWTAM winter surface conditions are modeled by <a href="/models#AirportHeliportContaminationType">models.AirportHeliportContaminationType</a>, <a href="/models#RunwayContaminationType">models.RunwayContaminationType</a>, and <a href="/models#SurfaceContaminationLayerType">models.SurfaceContaminationLayerType</a>.
`
